const $=s=>document.querySelector(s),img=p=>'https://image.tmdb.org/t/p/w500'+p;let saved;try{saved=JSON.parse(localStorage.getItem('playpipoca-list')||'[]');if(!Array.isArray(saved))saved=[]}catch{saved=[]}let view='home',genre='Todos',sortRating=false,heroIndex=0;const featured=[films[0],films[1],films[6]];const genres=['Todos','Ação','Aventura','Comédia','Drama','Ficção científica','Animação','Suspense'];
function toast(message){$('.toast').textContent=message;$('.toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('.toast').classList.remove('show'),2500)}
function toggleSave(id){const exists=saved.includes(id);saved=exists?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('playpipoca-list',JSON.stringify(saved))}catch{toast('Não foi possível salvar neste navegador.');return}render();updateHeroSave();if($('#details').open)detail(id);toast(exists?'Filme removido da sua lista.':'Adicionado à sua lista. Prepare a pipoca!')}
function render(){const query=$('#search').value.trim().toLocaleLowerCase('pt-BR');let result=films.filter(f=>(view!=='series'||f.type==='series')&&(view!=='movies'||f.type!=='series')&&(view!=='list'||saved.includes(f.id))&&(genre==='Todos'||f.genre===genre||(genre==='Aventura'&&[1,2,5,12].includes(f.id)))&&(`${f.title} ${f.genre} ${f.director}`).toLocaleLowerCase('pt-BR').includes(query));if(sortRating)result.sort((a,b)=>b.rating-a.rating);$('#count').textContent=saved.length;$('#result-count').textContent=`${result.length} títulos`;
$('#grid').innerHTML=result.map(f=>`<article class="card"><button class="poster-button" data-detail="${f.id}" aria-label="Ver detalhes de ${f.title}"><img src="${img(f.poster)}" alt="Pôster de ${f.title}" loading="lazy"><span class="rating">★ ${f.rating.toFixed(1)}</span><span class="poster-play">▶</span></button><div class="card-info"><div><h4>${f.title}</h4><p>${f.year} <span>·</span> ${f.genre}</p></div><button class="save ${saved.includes(f.id)?'saved':''}" data-save="${f.id}" aria-label="${saved.includes(f.id)?'Remover':'Adicionar'} ${f.title} ${saved.includes(f.id)?'da':'à'} minha lista">${saved.includes(f.id)?'✓':'＋'}</button></div></article>`).join('');$('#empty').hidden=!!result.length;$('#empty-text').textContent=view==='list'?'Salve filmes no botão + para montar sua próxima sessão.':'Tente outro título ou gênero.';document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(+b.dataset.detail));document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>toggleSave(+b.dataset.save));document.querySelectorAll('.poster-button img').forEach(i=>i.onerror=()=>{i.style.opacity='.15';i.alt='Pôster indisponível'})}
function trailer(f){window.open('https://www.youtube.com/watch?v='+f.trailer,'_blank','noopener,noreferrer')}
function detail(id){const f=films.find(f=>f.id===id);$('#detail-body').innerHTML=`<img class="detail-image" src="https://image.tmdb.org/t/p/w1280${f.back||f.poster}" alt="${f.title}"><div class="detail-content"><span class="section-kicker">${f.type==='series'?'SÉRIE':'FILME'} · ${f.genre.toUpperCase()}</span><h2>${f.title}</h2><div class="metadata"><b>★ ${f.rating}</b><span>${f.year}</span><span class="age">${f.age}</span><span>${f.time}</span></div><p>${f.description}</p><p><strong>Direção:</strong> ${f.director}<br><strong>Elenco:</strong> ${f.cast}</p><div class="detail-actions"><button class="primary" id="detail-trailer">▶ Assistir trailer</button><button class="secondary" id="detail-save">${saved.includes(id)?'✓ Na minha lista':'＋ Minha lista'}</button></div><p style="font-size:10px;margin-bottom:0">Trailer aberto no YouTube. Filme completo não disponível nesta versão.</p></div>`;$('#detail-trailer').onclick=()=>trailer(f);$('#detail-save').onclick=()=>toggleSave(id);if(!$('#details').open)$('#details').showModal()}
function updateHeroSave(){$('#hero-save').textContent=saved.includes(featured[heroIndex].id)?'✓':'＋';$('#hero-save').setAttribute('aria-label',saved.includes(featured[heroIndex].id)?'Remover da minha lista':'Adicionar à minha lista')}
function hero(){const f=featured[heroIndex];$('.hero').style.backgroundImage=`url(https://image.tmdb.org/t/p/original${f.back||f.poster})`;$('h1').textContent=f.title.toUpperCase();$('.hero .metadata').innerHTML=`<b>★ ${f.rating}</b><span>${f.year}</span><span class="age">${f.age}</span><span>${f.time}</span><span>${f.genre}</span>`;$('.hero-description').textContent=f.description;$('.slide-counter b').textContent=String(heroIndex+1).padStart(2,'0');updateHeroSave()}
$('.filters').innerHTML=genres.map(g=>`<button class="${g===genre?'active':''}" aria-pressed="${g===genre}">${g}</button>`).join('');$('.filters').onclick=e=>{if(e.target.tagName!=='BUTTON')return;genre=e.target.textContent;$('.filters').querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.textContent===genre);b.setAttribute('aria-pressed',b.textContent===genre)});render()};$('#search').oninput=render;$('#sort').onclick=()=>{sortRating=!sortRating;$('#sort').textContent=sortRating?'↕ Melhor avaliação':'↕ Mais populares';render()};document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n===b));$('#page-title').textContent={home:'O que vamos assistir hoje?',movies:'Encontre seu próximo filme',series:'Mais um episódio?',list:'Sua próxima sessão começa aqui'}[view];$('#row-title').textContent={home:'↗ Em alta agora',movies:'Explore os filmes',series:'Séries para maratonar',list:'Minha lista'}[view];render();$('.catalog').scrollIntoView({behavior:'smooth',block:'start'})});$('#hero-play').onclick=()=>trailer(featured[heroIndex]);$('#hero-info').onclick=()=>detail(featured[heroIndex].id);$('#hero-save').onclick=()=>toggleSave(featured[heroIndex].id);$('#next').onclick=()=>{heroIndex=(heroIndex+1)%featured.length;hero()};$('#prev').onclick=()=>{heroIndex=(heroIndex+featured.length-1)%featured.length;hero()};$('.close').onclick=()=>$('#details').close();$('#details').onclick=e=>{if(e.target===$('#details'))$('#details').close()};function focusSearch(){$('.catalog').scrollIntoView({behavior:'smooth'});$('#search').focus()}$('.search-toggle').onclick=focusSearch;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();focusSearch()}});$('.avatar').onclick=()=>toast('Perfil local • Sua lista fica salva neste navegador.');$('#reset').onclick=()=>{view='home';genre='Todos';$('#search').value='';document.querySelector('[data-view="home"]').click();$('.filters button').click()};render();updateHeroSave();
